"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[7578],{7578:(e,a,t)=>{t.d(a,{_:()=>i});let i={a11y:{skipToContent:"К основному содержимому"},brand:{name:"Volnami",logo:{full:"/volnami-c7-v615/logo/volnami-full.svg",icon:"/volnami-c7-v615/logo/volnami-icon.svg",wordmark:"/volnami-c7-v615/logo/volnami-wordmark.svg"}},header:{cta:{label:"Начнём с брифа",href:"#contacts"},telegram:{label:"Telegram",handle:"@vvolnami",href:"https://t.me/vvolnami"},menuLabel:"Меню",menuCloseLabel:"Закрыть"},nav:[{label:"Главная",href:"#hero"},{label:"О нас",href:"#about"},{label:"Услуги",href:"#services"},{label:"Кейсы",href:"#cases"},{label:"Отзывы",href:"#testimonials"},{label:"Контакты",href:"#contacts"}],hero:{sloganLines:["Плывём в потоке\xa0идей","создаём\xa0результат."],subtitle:"Стратегия, дизайн, digital и продакшн — в одной команде, с заботой о вашем продукте."},about:{title:"О нас",paragraphs:["Volnami — креативное агентство полного цикла. Работаем на стыке стратегии, дизайна и технологий: ведём проект от первого брифа до готового продукта.","Мы вкладываем душу в каждый проект и творим без наценки за громкое имя. Внимательно слушаем и задаём правильные вопросы, чтобы вместе достигать крутых результатов."]},process:{title:"Как мы работаем?",steps:[{title:"Бриф",description:"Выявляем потребности вашего бизнеса."},{title:"Анализ",description:"Проводим исследования рынка, конкурентов и аудитории."},{title:"Стратегия",description:"Определяем и согласовываем концепцию и план реализации."},{title:"Творим. Удивляем."}]},services:{title:"Услуги",list:[{index:1,title:"Стратегия",lead:"Помогаем понять, куда расти, и строим план, как туда добраться.",items:["Стратегия развития и продвижения бренда","Подготовка к запуску новых продуктов","План по захвату новых рынков"],closing:"Начинаем с анализа рынка, конкурентов и аудитории — потому что сильная стратегия строится на фактах и цифрах, а не на догадках."},{index:2,title:"Брендинг и дизайн",lead:"Превращаем смыслы в узнаваемые образы. Работаем с брендами на любом этапе: от рождения до громких кампаний.",items:["Нейминг и айдентика","Брендбук и гайдлайны","Креативы для рекламных кампаний","Упаковка и полиграфия","Интерфейсы (UI/UX)"],closing:"От логотипа до рекламного баннера — всё говорит на одном языке бренда."},{index:3,title:"Диджитал",lead:"Продвигаем бренды с опорой на экономическую эффективность.",items:["Ведение социальных сетей (SMM)","Таргет и SEO","CRM","PR","BTL и спецпроекты"],closing:"Строим долгосрочный план продвижения и привлекаем новую аудиторию."},{index:4,title:"Web и чат-боты",lead:"Разрабатываем IT-продукты — сайты и чат-боты под любые бизнес-задачи.",items:["Лендинги и Taplink","Многостраничные сайты и веб-сервисы","Чат-боты для Telegram, WhatsApp, ВК и других платформ","Интеграции с CRM и уведомлениями"],closing:"Кстати, именно так родился текст, который ты сейчас читаешь, — мы делаем сайты не только для клиентов, но и для себя."}]},cases:{title:"Кейсы",portfolioLink:{label:"портфолио дизайнера",href:"https://www.behance.net/c796bc1d"},list:[{slug:"kulek",title:"Картофельный Кулёк",teaser:"Кафе быстрого питания \xabКартофельный Кулёк\xbb подаёт хрустящую картошку фри с разными начинками в фирменной упаковке-кульке — быстро, ярко, по-уличному.",blocks:[{kind:"lead",text:"Кафе быстрого питания \xabКартофельный Кулёк\xbb подаёт хрустящую картошку фри с разными начинками в фирменной упаковке-кульке — быстро, ярко, по-уличному."},{kind:"section",heading:"Задача",paragraphs:["Разработать брендинг продукта: упаковку-кулёк и POS-материалы для открытия и промо-акций кафе."]},{kind:"section",heading:"Решение",paragraphs:["Единый визуальный язык — глубокий фиолетовый и сочный жёлто-золотой. Фирменная упаковка в форме кулька, листовки на открытие, постеры под акции."]},{kind:"section",heading:"Почему фиолетовый",paragraphs:["В стрит-фуде с фри правит красно-жёлтый — KFC, Burger King. Аппетитно, но на фудкорте всё сливается в один фон: слишком много одинакового. Фиолетовый — редкость для еды, поэтому глаз цепляется за него на расстоянии: мозг не ждёт его рядом с картошкой. Ставка на \xabзаметь меня в потоке\xbb, а не на классический аппетитный код."]},{kind:"section",heading:"Почему жёлтый",paragraphs:["Это цвет самого продукта — хрустящей картошки. Упаковка не спорит с фото еды, а продолжает его. А дуэт фиолетового с золотым сам по себе читается как премиум."]},{kind:"section",heading:"Форма",paragraphs:["Стекающий узор превращает кулёк в рожок мороженого. Мозг переносит ассоциацию \xabрожок = лакомство\xbb на картошку — так рождается импульсная покупка: берут не от голода, а потому что \xabхочется\xbb."]},{kind:"section",heading:"Итог",paragraphs:["Система работает на одно: выделиться в ряду одинаковых вывесок нестандартным цветом и превратить картошку в маленькое удовольствие через форму и графику. Дизайн продаёт не только продукт, но и повод купить его прямо сейчас."]}],visuals:[{src:"/volnami-c7-v615/cases/kulek/kulek-1.webp",alt:"Фирменная упаковка-кулёк с панированными стрипсами и логотип \xabКартофельный Кулёк\xbb золотом на глубоком фиолетовом фоне",width:1800,height:1125},{src:"/volnami-c7-v615/cases/kulek/kulek-inhand.webp",alt:"Упаковка-кулёк с картошкой фри и начинкой в руке, вид вблизи",width:1005,height:1314},{src:"/volnami-c7-v615/cases/kulek/kulek-dieline.webp",alt:"Развёртка упаковки-кулька с проставленными размерами и углом 45 градусов",width:1710,height:1244},{src:"/volnami-c7-v615/cases/kulek/kulek-food.webp",alt:"Картофельные дольки с сосисками, солёными огурцами, сыром и хрустящим луком в фирменной упаковке, вид сверху",width:987,height:791},{src:"/volnami-c7-v615/cases/kulek/kulek-flyer.webp",alt:"Листовка к торжественному открытию кафе с предложением комбо за 589 рублей",width:1326,height:1919},{src:"/volnami-c7-v615/cases/kulek/kulek-pos.webp",alt:"POS-постер акции \xabКуриные стрипсы 5 штук\xbb с выбором соуса за 379 рублей",width:1395,height:1962},{src:"/volnami-c7-v615/cases/kulek/kulek-terrace.webp",alt:"Летняя веранда кафе с фирменным брендированным стендом, жёлтыми столами и фиолетовыми стульями",width:987,height:1310}]},{slug:"transformaciya-realnosti",title:"ТРАНСФОРМАЦИЯ РЕАЛЬНОСТИ:",teaser:"Первая Всероссийская конференция режиссёров театрализованных представлений и праздников, постановщиков event и креативных направлений — мероприятие, которое впервые собрало на одной площадке профессионалов индустрии.",blocks:[{kind:"lead",text:"Первая Всероссийская конференция режиссёров театрализованных представлений и праздников, постановщиков event и креативных направлений — мероприятие, которое впервые собрало на одной площадке профессионалов индустрии."},{kind:"section",heading:"Задача:",paragraphs:["разработать полную айдентику и комплект полиграфии для конференции — от программы до оформления сцены и промо в сети. Деловое мероприятие не должно было выглядеть шаблонно-корпоративным — оформление должно было транслировать смысл названия: трансформацию, движение, будущее индустрии."]},{kind:"section",heading:"Что сделали:",paragraphs:["собрали фирменный комплект материалов под единую айдентику — программу мероприятия, брендволл 4\xd72 м с логотипами более 20 партнёров, роллап, именные приглашения и бейджи участников, футболки и блокноты для команды, афиши и баннеры для интернет-площадок."]}],visuals:[{src:"/volnami-c7-v615/cases/transformaciya-realnosti/tr-12.webp",alt:"Титульный баннер конференции с датой третье апреля 2023 года",width:1800,height:985},{src:"/volnami-c7-v615/cases/transformaciya-realnosti/tr-4.webp",alt:"Афиша конференции и её размещение на интернет-площадке",width:1800,height:985},{src:"/volnami-c7-v615/cases/transformaciya-realnosti/tr-6.webp",alt:"Именные приглашения на конференцию, стопка карточек",width:1800,height:985},{src:"/volnami-c7-v615/cases/transformaciya-realnosti/tr-7.webp",alt:"Программа мероприятия: обложка и развороты",width:1800,height:985},{src:"/volnami-c7-v615/cases/transformaciya-realnosti/tr-5.webp",alt:"Бейджи участников на лентах: именной и \xabСтудент\xbb",width:1800,height:985},{src:"/volnami-c7-v615/cases/transformaciya-realnosti/tr-9.webp",alt:"Роллап и футболки команды с фирменной символикой конференции",width:1800,height:985},{src:"/volnami-c7-v615/cases/transformaciya-realnosti/tr-10.webp",alt:"Фирменные блокноты участников",width:1800,height:985},{src:"/volnami-c7-v615/cases/transformaciya-realnosti/tr-8.webp",alt:"Брендволл четыре на два метра с логотипами более двадцати партнёров",width:1800,height:985},{src:"/volnami-c7-v615/cases/transformaciya-realnosti/tr-11.webp",alt:"Финал конференции: участники на сцене под конфетти",width:1800,height:985},{src:"/volnami-c7-v615/cases/transformaciya-realnosti/tr-1.webp",alt:"Сцена конференции: спикеры в креслах на фоне брендволла с логотипами партнёров",width:1800,height:985}]},{slug:"ekorancho",title:"ЭКОРАНЧО:",teaser:"Полный цикл брендинга и цифровая экосистема для магазина органических продуктов с прицелом на масштабирование в сеть: коммуникационная платформа, логотип и айдентика, авторские иллюстрации, упаковка и POS-материалы для торгового зала.",blocks:[{kind:"section",heading:"Задача:",paragraphs:["Полный цикл брендинга и цифровая экосистема для магазина органических продуктов с прицелом на масштабирование в сеть: коммуникационная платформа, логотип и айдентика, авторские иллюстрации, упаковка и POS-материалы для торгового зала."]},{kind:"section",heading:"Визуальный стиль",paragraphs:["Тёплая зелёно-коричневая палитра, росток, округлые мягкие формы — про натуральность и уют."]},{kind:"section",heading:"Почему такая палитра",paragraphs:["Зелёный в органике — не выбор, а ожидание: первый сигнал, который глаз считывает за долю секунды на полке или в приложении — \xabэто про природу\xbb. Но чистый яркий зелёный давно стал штампом — так выглядит половина эко-брендов, и глаз его уже не замечает. Поэтому добавили тёплый землистый коричневый: он читается как настоящая почва и создаёт ощущение фермы, а не лабораторной стерильности."]},{kind:"section",heading:"Экосистема",paragraphs:["Под ключ спроектировали мобильное приложение: каталог, персональные рекомендации, рецепты из купленных продуктов, история покупок, накопительные баллы."]}],visuals:[{src:"/volnami-c7-v615/cases/ekorancho/eko-system.webp",alt:"Фирменный стиль \xabЭкоРанчо\xbb: логотип, приложение, упаковка и иллюстрации",width:1354,height:789},{src:"/volnami-c7-v615/cases/ekorancho/eko-app.webp",alt:"Экраны мобильного приложения \xabЭкоРанчо\xbb: каталог, карточки товаров и корзина",width:922,height:789},{src:"/volnami-c7-v615/cases/ekorancho/eko-illustr.webp",alt:"Авторские иллюстрации категорий продуктов в круглых значках",width:922,height:624},{src:"/volnami-c7-v615/cases/ekorancho/eko-phones.webp",alt:"Экраны приложения с рецептами из купленных продуктов",width:922,height:789},{src:"/volnami-c7-v615/cases/ekorancho/eko-promo.webp",alt:"Промо-материалы приложения: буклет и экраны сервиса доставки",width:922,height:632}]},{slug:"desyatoe-korolevstvo",title:"ДЕСЯТОЕ КОРОЛЕВСТВО",teaser:"",pending:!0,blocks:[],externalLink:{label:"остальные мокапы",href:"https://disk.yandex.ru/d/jTHfuHTC65HNzQ"},visuals:[]},{slug:"miratorg-extra-meat",title:"МИРАТОРГ КОРМА EXTRA MEAT",teaser:"С нашим партнёром АПХ \xabМираторг\xbb, помимо регулярных креативных задач, нам довелось поработать над уникальным кейсом — разработкой новой премиальной линейки кормов для хвостатых любимцев.",blocks:[{kind:"lead",text:"С нашим партнёром АПХ \xabМираторг\xbb, помимо регулярных креативных задач, нам довелось поработать над уникальным кейсом — разработкой новой премиальной линейки кормов для хвостатых любимцев."},{kind:"section",heading:"Задача",items:["Разработать дизайн упаковок сухих и влажных кормов для кошек и собак.","Поставить бренд в один ряд с премиальными конкурентами — Blitz, Sirius, Acana, Orijen — и повысить его привлекательность на полке.","Нативно встроить в коммуникацию ключевые УТП холдинга: собственное производство ингредиентов и полный контроль качества от поля до прилавка."]},{kind:"section",heading:"Контекст",paragraphs:["Несмотря на высокое качество составов, продукты холдинга не могли занять нишу в премиальном сегменте — мешали устаревший дизайн и отсутствие коммуникационной платформы. Ключевые преимущества — собственное производство ингредиентов, контроль качества от поля до прилавка, свежее мясо в составе, включая премиальную говядину Black Angus, — до потребителя просто не доходили. Решено было разработать новую линейку, которая будет полностью соответствовать рынку и ожиданиям премиального покупателя."]},{kind:"section",heading:"Подход",paragraphs:["Собрали бренд так, чтобы он не просто выглядел премиально, а работал на бизнес: выделялся на полке, притягивал взгляд и оправдывал цену — не обещанием, а тем, что видно с первого взгляда.","Разработку начали с коммуникационной платформы — с чем должен ассоциироваться продукт. Так родилась идея фермерского подхода: натурально, экологично, под полным контролем производителя, от поля до миски. И главный твист — кто на самом деле ставит оценку: не маркетологи, а тот, для кого всё это создаётся. Съеденный корм — самая честная проверка: экспертиза хвостатого потребителя."]},{kind:"section",heading:"Что сделали",subsections:[{heading:"Выявили коммуникационную платформу",text:"Собрали позиционирование \xabМираторг — когда забота начинается в поле\xbb и весь смысловой ряд вокруг него: ферма, натуральность, полный контроль производителя и экспертиза, которую невозможно подделать, потому что её выдаёт сам питомец."},{heading:"Вынесли ключевые преимущества на упаковку",text:"Раньше главные аргументы холдинга — собственное производство, контроль качества — терялись в составе. Мы вывели их на лицевую сторону, туда, где покупатель принимает решение за секунды."},{heading:"Добавили цветовую навигацию",text:"Ввели цветовую кодировку по вкусу и типу белка и отдельную маркировку по типу животного — котята, стерилизованные и так далее, — чтобы бренд считывался быстрее в момент выбора."},{heading:"Выстроили эмоциональное восприятие бренда",text:"Добавили в визуальный ряд животных на природе — это работает не как декор, а как ассоциация: натуральность и качество считываются на подсознании ещё до того, как прочитан состав. А корпоративные клейма и сертификаты убрали с переднего плана, чтобы они не спорили за внимание с тем, что покупателю правда важно в момент выбора."}]}],visuals:[]},{slug:"hobby-world",title:"HOBBY WORLD/ HOBBY GAMES",teaser:"Регулярное креативное сопровождение холдинга Hobby World — продвижение игр издательства, а также фирменной сети Hobby Games.",blocks:[{kind:"lead",text:"Регулярное креативное сопровождение холдинга Hobby World — продвижение игр издательства, а также фирменной сети Hobby Games."},{kind:"section",heading:"Задача:",paragraphs:["формировать и поддерживать единый фирменный стиль бренда на всех точках контакта — в магазинах, на сайте, в рекламе — и обеспечивать постоянный поток материалов для продвижения."]},{kind:"section",heading:"Что сделали:",paragraphs:["для сети Hobby Games разрабатывали и поддерживали фирменный стиль в рознице — POS-материалы, торговое оборудование, ролл-апы и брендированные стойки для выкладки товара.","Отдельное направление — иллюстрации и вёрстка для настольных игр самого издательства Hobby World: от визуальной концепции и персонажей до подготовки упаковки и игровых полей к печати."]},{kind:"group",title:"Мосигра",blocks:[{kind:"lead",text:"Креативное сопровождение сети магазинов настольных игр и подарков Мосигра."},{kind:"section",heading:"Задача:",paragraphs:["формировать и поддерживать единый фирменный стиль бренда на всех точках контакта — в магазинах, на сайте, в рекламе — и обеспечивать постоянный поток материалов для продвижения."]},{kind:"section",heading:"Что сделали:",paragraphs:["поддерживали визуальный образ бренда на сайте mosigra.ru и в рознице — POS-материалы, торговое оборудование, ролл-апы и другое."]}]}],visuals:[]},{slug:"ora-ora",title:"Ora Ora",teaser:"Сеть магазинов Ora Ora (\xabАниме и всё такое\xbb) создавалась с нуля — от концепции точек продаж до сайта, — и мы участвовали в этом процессе с самого старта: разработка визуального стиля, брендбук, концепция интерьера, сайт, а также постоянное креативное сопровождение рекламных кампаний бренда.",blocks:[{kind:"lead",text:"Сеть магазинов Ora Ora (\xabАниме и всё такое\xbb) создавалась с нуля — от концепции точек продаж до сайта, — и мы участвовали в этом процессе с самого старта: разработка визуального стиля, брендбук, концепция интерьера, сайт, а также постоянное креативное сопровождение рекламных кампаний бренда."},{kind:"section",heading:"Задача",paragraphs:["Помочь бренду выйти на рынок с узнаваемым, живым образом — таким, чтобы он говорил на одном языке с аудиторией аниме- и поп-культуры, а не выглядел как обезличенный магазин мерча, — и дальше поддерживать этот образ в продвижении."]},{kind:"section",heading:"Контекст",paragraphs:["Аудитория аниме-магазинов — это в первую очередь молодая, визуально насмотренная публика, которая живёт в эстетике манги, кавайной культуры и Y2K-неона в соцсетях и хорошо считывает фальшь: типовой \xabмагазин с постерами\xbb для неё не работает, нужен бренд, который выглядит так, будто его придумали свои, а не корпорация, которая решила заработать на тренде."]},{kind:"section",heading:"Подход",paragraphs:["При участии в разработке визуального стиля мы отталкивались не от \xabдавайте налепим анимешных картинок\xbb, а от вопроса — как сделать так, чтобы бренд был узнаваем сам по себе, не одалживая чужие франшизы (тот же Наруто или Сейлор Мун использовать в айдентике напрямую нельзя — это чужая интеллектуальная собственность), но при этом разговаривал с аудиторией на её визуальном языке."]},{kind:"section",heading:"Выбор цветовой палитры",paragraphs:["Неоновый розовый и кислотно-лаймовый на светлой, почти белой базе — это прямая отсылка к эстетике kawaii и Y2K-неона, которая доминирует в визуальной культуре аниме-сообщества в соцсетях: аудитория уже считывает эти цвета как \xabсвоё\xbb ещё до того, как зайдёт в магазин. При этом светлая база — осознанное решение не уходить в кислотный \xabдетский\xbb кич: она держит баланс между \xabярко и весело\xbb и \xabвзрослый ритейл, в который приятно зайти\xbb."]},{kind:"section",heading:"Что делали?",paragraphs:["Приняли участие в разработке визуального стиля сети — брендбук с системой авторской иллюстрации и фирменной графики, концепция интерьера магазинов, сайта бренда, разработали креативы в рамках созданного брендбука: промо-материалы, баннеры и макеты под рекламные кампании."]}],visuals:[]}]},testimonials:{title:"Отзывы",list:[{paragraphs:["Заказывал у ребят оформление для своего магазина продуктов и мобильное приложение. Отработали на все 100%, а самое главное, видно было, что искренне вовлеклись и переживали, как за своё. В наше время такое отношение — редкость.","Огромное спасибо!:)"],name:"ИП Короткевич"},{paragraphs:["Работаем с Volnami уже давно, и за это время прошлись по разным видам задач и с разными обстоятельствами - с горящими сроками; без четкого тз - на покреативить; с большими бюджетами, требующими глубокого аналитического подхода. Вы команда, которая сильно выручает и работает качественно. Агентство за которым не нужно проверять - редкость на нашем опыте. Плюс отмечу реальную ориентированность на аналитику, конкурентов и цифры, а не просто красивую картинку.","Спасибо, что быстро включаетесь, оперативно вносите правки, также за легкую коммуникацию. Продолжайте в том же духе."],name:"Костенко А.А.",role:"Ведущий бренд-менеджер ООО \xabМираторг\xbb"},{paragraphs:["Считаю, показательным, что одна команда закрыла задачи сразу по всему холдингу - рекламные материалы для розничных магазинов Hobby games и Мосигра, верстка сайтов и диджитал продвижение, иллюстрации для игр, да и много чего еще. В общем, рады такому сотрудничеству.","Справлялись всегда оперативно и без раздутых смет, гибкие в сроках и форматах задач. В общем, ребята классные и работать с ними приятно. Спасибо!"],name:"Короткевич Е.С",role:"Digital-маркетолог ООО \xabHobby World\xbb"},{paragraphs:["Заказывала международный сайт для предприятия — много технического материала, но оформили грамотно, структурировано, предложили хороший дизайн. Помогли разобраться в технических аспектах работы с сайтами с нуля (домен, согласие на обработку персональных данных и т д), сделали удобную систему управления и поддерживали пока не разобралась. Очень довольна результатом."],name:"Васильева О.Т.",role:"Директор по коммуникациям ООО \xabОрганические кислоты\xbb"}]},contacts:{title:"Готовы к новым волнам роста?",paragraphs:["Готовы обсудить ваши идеи? Свяжитесь с нами — мы ответим на все вопросы и найдём лучшее решение для вашего бизнеса!","Нам интересны любые проекты. Большие, маленькие, смелые — давайте обсудим, что у вас на уме."],cta:{label:"рассчитать проект"},telegram:{label:"Telegram",value:"@vvolnami",href:"https://t.me/vvolnami"},email:{label:"Email",value:"v.volnami@yandex.ru",href:"mailto:v.volnami@yandex.ru"},phone:{label:"Телефон",value:"+7 926 126 8125",href:"tel:+79261268125"}},privacyPlaceholder:"[[ РЕКВИЗИТЫ ОПЕРАТОРА ]]"}}}]);